props.onPress:
{() => {
                  if (__DEV__) {
                    setAiMode((active) => !active);
                    requestAnimationFrame(() => searchInputRef.current?.focus());
                  } else {
                    Keyboard.dismiss();
                    router.push({ pathname: '/plan', params: { role: 'foodie' } });
                  }
                }}

props.onLayout:
{index < SHEET_MEDIUM_ROWS ? (event) => {
                        const height = Math.max(60, Math.ceil(event.nativeEvent.layout.height));
                        setSheetRowHeights((current) => current[index] === height ? current : current.map((value, row) => row === index ? height : value));
                      } : undefined}

props.onPressIn:
{() => {
                        // El toque resalta el pin; desplazar la lista no
                        // debe cambiar la posición ni los resultados del mapa.
                        if (match.patio.latitude <= 0) return;
                        setPressedPinId(match.patio.id);
                      }}

props.onPress:
{() => Alert.alert(
                    `Racha de ${streak} ${streak === 1 ? 'día' : 'días'}`,
                    `Llevas ${streak} ${streak === 1 ? 'día seguido publicando' : 'días seguidos publicando'} tu menú. Se rompe si dejas pasar un día completo sin publicar.`,
                  )}

{() => {
                      if (selected) {
                        const next = result.tipos.filter((id) => id !== item.id);
                        update({ tipos: next, tipo: next[0] ?? 'otro' });
                        Haptics.selectionAsync();
                      } else if (!atMax) {
                        const next = [...result.tipos, item.id];
                        update({ tipos: next, tipo: next[0] });
                        Haptics.selectionAsync();
                      } else {
                        Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning);
                      }
                    }}

props.style:
{[
                      s.typeOption,
                      { backgroundColor: colors.surface, borderColor: selected ? colors.accent : colors.border },
                      locked && s.typeOptionLocked,
                    ]}

props.onPress:
{async () => {
            try {
              const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images'], allowsEditing: true, aspect: [1, 1], quality: 0.75 });
              if (!result.canceled && result.assets[0]) setAvatarUri(result.assets[0].uri);
            } catch {
              Alert.alert(noWidow('No pudimos abrir tus fotos'), noWidow('Revisa los permisos de Patio en Ajustes e inténtalo de nuevo.'));
            }
          }}

{() => {
                            if (replyCount > 0) {
                              setExpandedThreads((current) => ({ ...current, [reviewKey]: !(current[reviewKey] ?? false) }));
                              setReplyingTo(null);
                              setReplyingToComment(null);
                            } else {
                              setReplyingTo((current) => current === reviewKey ? null : reviewKey);
                            }
                          }}

{() => {
                            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light).catch(() => {});
                            setReviewLikes((current) => ({ ...current, [reviewKey]: { mine: !like.mine, count: Math.max(0, like.count + (like.mine ? -1 : 1)) } }));
                            if (review.reviewId) void toggleReviewLike(review.reviewId);
                          }}

{() => {
                                    setReplyingToComment({ reviewKey, parentId, author: reply.mine ? 'Tú' : reply.author });
                                    setReplyingTo(null);
                                    setReplyDraft('');
                                  }}

{() => {
                                          const next = replyDraft.trim();
                                          const child: ReviewThreadReply = { id: `${reviewKey}-mine-${Date.now()}`, author: 'Tú', body: next, likes: 0, mine: true, parentId: reply.id };
                                          setReviewReplies((current) => ({ ...current, [reviewKey]: [...(current[reviewKey] ?? []), child] }));
                                          setReplyDraft('');
                                          setReplyingToComment(null);
                                        }}

{() => {
                              const next = replyDraft.trim();
                              const reply: ReviewThreadReply = {
                                id: `${reviewKey}-mine-${Date.now()}`,
                                author: 'Tú',
                                body: next,
                                likes: 0,
                                mine: true,
                              };
                              setReviewReplies((current) => ({ ...current, [reviewKey]: [...(current[reviewKey] ?? []), reply] }));
                              setExpandedThreads((current) => ({ ...current, [reviewKey]: true }));
                              setReplyDraft('');
                              setReplyingTo(null);
                            }}

{() => {
                      void Haptics.selectionAsync();
                      setActivePicker({ dia: item.id, field });
                    }}

props.onMore:
{mode === 'move' ? undefined : () => Alert.alert(collection.title, undefined, [
          { text: 'Renombrar', onPress: () => startRename(collection) }, { text: 'Eliminar', style: 'destructive', onPress: () => remove(collection) }, { text: 'Cancelar', style: 'cancel' },
        ])}

props.onPress:
{() => {
              if (creating) { setCreating(false); Keyboard.dismiss(); }
              else if (canReturnToSource) { setChoosingSource(true); setDestinationId(null); }
              else setCreating(true);
            }}
